<template>
  <div class="campaigns-page">
    <div class="page-head">
      <div><div class="eyebrow">投放管理 / Meta</div><h2>广告系列</h2><p>统一查看、同步和控制 Campaign、AdSet 与 Ad。</p></div>
      <div><el-button :loading="loading" @click="refresh">刷新</el-button><el-button type="primary" @click="sync">同步 Meta</el-button></div>
    </div>
    <el-alert v-if="taskNotice" :title="taskNotice" :type="taskNoticeType" :closable="true" show-icon style="margin-bottom: 12px" @close="taskNotice = ''" />
    <el-tabs v-model="activeTab" @tab-change="onTabChange">
      <el-tab-pane label="广告系列" name="campaigns">
        <el-card shadow="never">
          <div class="filters"><el-input v-model="keywordFilter" placeholder="搜索广告系列名称或 Meta ID" clearable @keyup.enter="loadCampaigns" /><el-input v-model="accountFilter" placeholder="广告账户 ID" clearable @keyup.enter="loadCampaigns" /><el-select v-model="statusFilter" placeholder="系统状态" clearable @change="loadCampaigns"><el-option label="启用" value="ACTIVE" /><el-option label="暂停" value="PAUSED" /><el-option label="已归档" value="ARCHIVED" /><el-option label="已删除" value="DELETED" /></el-select><el-button @click="loadCampaigns">筛选</el-button></div>
          <div class="batch-toolbar"><span>已选 {{ selectedCampaigns.length }} 个广告系列</span><el-button size="small" :disabled="!selectedCampaigns.length" @click="syncSelected('CAMPAIGN', selectedCampaigns)">批量同步</el-button><el-button size="small" :disabled="!selectedCampaigns.length" @click="batchAction('PAUSE', 'CAMPAIGN', selectedCampaigns)">批量暂停</el-button><el-button size="small" :disabled="!selectedCampaigns.length" @click="batchAction('ENABLE', 'CAMPAIGN', selectedCampaigns)">批量启用</el-button><el-button size="small" type="warning" :disabled="!selectedCampaigns.length" @click="batchAction('ARCHIVE', 'CAMPAIGN', selectedCampaigns)">批量归档</el-button><el-button size="small" type="danger" :disabled="!selectedCampaigns.length" @click="batchAction('DELETE', 'CAMPAIGN', selectedCampaigns)">批量移除</el-button><el-button size="small" type="success" :disabled="!selectedCampaigns.length" @click="batchAction('RESTORE', 'CAMPAIGN', selectedCampaigns)">批量恢复</el-button></div>
          <el-table :data="campaigns" v-loading="loading" @selection-change="selectedCampaigns = $event"><el-table-column type="selection" width="46" /><el-table-column prop="name" label="广告系列" /><el-table-column prop="account_name" label="广告账户" show-overflow-tooltip /><el-table-column prop="meta_campaign_id" label="Meta ID" /><el-table-column prop="objective" label="目标" /><el-table-column label="Meta 状态"><template #default="{ row }"><el-tag size="small" :type="row.meta_status === 'ACTIVE' ? 'success' : 'warning'">{{ row.meta_status || '未同步' }}</el-tag></template></el-table-column><el-table-column label="系统状态"><template #default="{ row }"><el-tag size="small" :type="row.status === 'ACTIVE' ? 'success' : 'info'">{{ row.status }}</el-tag></template></el-table-column><el-table-column prop="last_synced_at" label="最近同步" width="170" /><el-table-column label="操作" width="430"><template #default="{ row }"><el-button link type="primary" @click="showDetail(row, 'CAMPAIGN')">详情</el-button><el-button link type="primary" @click="syncSelected('CAMPAIGN', [row])">同步</el-button><el-button link type="primary" @click="openAdsets(row)">广告组</el-button><el-button v-if="['ACTIVE','PAUSED'].includes(row.status)" link type="warning" @click="changeStatus(row, 'CAMPAIGN')">{{ row.status === 'ACTIVE' ? '暂停' : '启用' }}</el-button><el-button v-if="['ACTIVE','PAUSED'].includes(row.status)" link type="danger" @click="archive(row, 'CAMPAIGN')">归档</el-button><el-button v-if="row.status !== 'DELETED'" link type="danger" @click="removePublished(row, 'CAMPAIGN')">移除</el-button><el-button v-if="['ARCHIVED','DELETED'].includes(row.status)" link type="success" @click="restore(row, 'CAMPAIGN')">恢复</el-button></template></el-table-column></el-table>
          <el-empty v-if="!loading && !campaigns.length" description="暂无广告系列，请先完成批量投放" />
        </el-card>
      </el-tab-pane>
      <el-tab-pane label="广告组" name="adsets">
        <el-card shadow="never">
          <div class="sub-head"><div class="selector-row"><el-select v-model="selectedCampaignId" placeholder="选择广告系列" filterable clearable @change="selectCampaign"><el-option v-for="item in campaigns" :key="item.id" :label="`${item.name} · ${item.account_name || item.meta_campaign_id}`" :value="item.id" /></el-select><el-select v-model="adsetStatusFilter" placeholder="状态" clearable @change="selectedCampaignId && loadAdsets(selectedCampaignId)"><el-option label="启用" value="ACTIVE" /><el-option label="暂停" value="PAUSED" /><el-option label="归档" value="ARCHIVED" /><el-option label="已移除" value="DELETED" /></el-select></div><el-button link @click="activeTab = 'campaigns'">返回广告系列</el-button></div>
          <div class="batch-toolbar"><span>已选 {{ selectedAdsets.length }} 个广告组</span><el-button size="small" :disabled="!selectedAdsets.length" @click="syncSelected('ADSET', selectedAdsets)">批量同步</el-button><el-button size="small" :disabled="!selectedAdsets.length" @click="batchAction('PAUSE', 'ADSET', selectedAdsets)">批量暂停</el-button><el-button size="small" :disabled="!selectedAdsets.length" @click="batchAction('ENABLE', 'ADSET', selectedAdsets)">批量启用</el-button><el-button size="small" type="warning" :disabled="!selectedAdsets.length" @click="batchAction('ARCHIVE', 'ADSET', selectedAdsets)">批量归档</el-button><el-button size="small" type="danger" :disabled="!selectedAdsets.length" @click="batchAction('DELETE', 'ADSET', selectedAdsets)">批量移除</el-button><el-button size="small" type="success" :disabled="!selectedAdsets.length" @click="batchAction('RESTORE', 'ADSET', selectedAdsets)">批量恢复</el-button></div>
          <el-table :data="adsets" v-loading="subLoading" @selection-change="selectedAdsets = $event"><el-table-column type="selection" width="46" /><el-table-column prop="name" label="广告组" /><el-table-column prop="meta_adset_id" label="Meta ID" /><el-table-column prop="optimization_goal" label="优化目标" /><el-table-column prop="daily_budget" label="日预算" /><el-table-column label="状态"><template #default="{ row }"><el-tag size="small" :type="row.status === 'ACTIVE' ? 'success' : 'info'">{{ row.status || '未知' }}</el-tag></template></el-table-column><el-table-column prop="last_synced_at" label="最近同步" width="170" /><el-table-column label="操作" width="460"><template #default="{ row }"><el-button link type="primary" @click="showDetail(row, 'ADSET')">详情</el-button><el-button link type="primary" @click="syncSelected('ADSET', [row])">同步</el-button><el-button link type="primary" @click="openAds(row)">查看广告</el-button><el-button v-if="['ACTIVE','PAUSED'].includes(row.status)" link type="warning" @click="changeStatus(row, 'ADSET')">{{ row.status === 'ACTIVE' ? '暂停' : '启用' }}</el-button><el-button v-if="['ACTIVE','PAUSED'].includes(row.status)" link type="danger" @click="archive(row, 'ADSET')">归档</el-button><el-button v-if="row.status !== 'DELETED'" link type="danger" @click="removePublished(row, 'ADSET')">移除</el-button><el-button v-if="['ARCHIVED','DELETED'].includes(row.status)" link type="success" @click="restore(row, 'ADSET')">恢复</el-button></template></el-table-column></el-table>
          <el-empty v-if="!subLoading && selectedCampaignId && !adsets.length" description="该广告系列暂无广告组" />
        </el-card>
      </el-tab-pane>
      <el-tab-pane label="广告" name="ads">
        <el-card shadow="never">
          <div class="sub-head"><div class="selector-row"><el-select v-model="selectedAdsetId" placeholder="选择广告组" filterable clearable @change="selectAdset"><el-option v-for="item in adsets" :key="item.id" :label="`${item.name} · ${item.meta_adset_id}`" :value="item.id" /></el-select><el-select v-model="adStatusFilter" placeholder="状态" clearable @change="selectedAdsetId && loadAds(selectedAdsetId)"><el-option label="启用" value="ACTIVE" /><el-option label="暂停" value="PAUSED" /><el-option label="归档" value="ARCHIVED" /><el-option label="已移除" value="DELETED" /></el-select></div><el-button link @click="activeTab = 'adsets'">返回广告组</el-button></div>
          <div class="batch-toolbar"><span>已选 {{ selectedAds.length }} 个广告</span><el-button size="small" :disabled="!selectedAds.length" @click="syncSelected('AD', selectedAds)">批量同步</el-button><el-button size="small" :disabled="!selectedAds.length" @click="batchAction('PAUSE', 'AD', selectedAds)">批量暂停</el-button><el-button size="small" :disabled="!selectedAds.length" @click="batchAction('ENABLE', 'AD', selectedAds)">批量启用</el-button><el-button size="small" type="warning" :disabled="!selectedAds.length" @click="batchAction('ARCHIVE', 'AD', selectedAds)">批量归档</el-button><el-button size="small" type="danger" :disabled="!selectedAds.length" @click="batchAction('DELETE', 'AD', selectedAds)">批量移除</el-button><el-button size="small" type="success" :disabled="!selectedAds.length" @click="batchAction('RESTORE', 'AD', selectedAds)">批量恢复</el-button></div>
          <el-table :data="ads" v-loading="subLoading" @selection-change="selectedAds = $event"><el-table-column type="selection" width="46" /><el-table-column prop="name" label="广告" /><el-table-column prop="meta_ad_id" label="Meta ID" /><el-table-column prop="meta_status" label="Meta 状态" /><el-table-column prop="status" label="系统状态" /><el-table-column prop="last_synced_at" label="最近同步" width="170" /><el-table-column label="操作" width="450"><template #default="{ row }"><el-button link type="primary" @click="showDetail(row, 'AD')">详情</el-button><el-button link type="primary" @click="syncSelected('AD', [row])">同步</el-button><el-button v-if="['ACTIVE','PAUSED'].includes(row.status)" link type="warning" @click="changeStatus(row, 'AD')">{{ row.status === 'ACTIVE' ? '暂停' : '启用' }}</el-button><el-button v-if="['ACTIVE','PAUSED'].includes(row.status)" link type="danger" @click="archive(row, 'AD')">归档</el-button><el-button v-if="row.status !== 'DELETED'" link type="danger" @click="removePublished(row, 'AD')">移除</el-button><el-button v-if="['ARCHIVED','DELETED'].includes(row.status)" link type="success" @click="restore(row, 'AD')">恢复</el-button></template></el-table-column></el-table>
          <el-empty v-if="!subLoading && selectedAdsetId && !ads.length" description="该广告组暂无广告" />
        </el-card>
      </el-tab-pane>
      <el-tab-pane label="异步任务" name="jobs">
        <el-card shadow="never">
          <el-alert v-if="batchResult" :type="batchResult.failed ? 'warning' : 'info'" show-icon closable @close="batchResult = null"><template #title>{{ batchResult.title }}</template><div class="result-summary">提交 {{ batchResult.count }} 个对象；{{ batchResult.message }} <el-button link type="primary" @click="loadJobs">刷新结果</el-button></div></el-alert>
          <div class="sub-head">投放任务结果</div><el-table :data="jobs" v-loading="jobLoading"><el-table-column prop="id" label="投放任务 ID" show-overflow-tooltip /><el-table-column prop="action_type" label="动作" /><el-table-column prop="status" label="状态" /><el-table-column label="结果"><template #default="{ row }"><span class="success-text">{{ row.success_count }}</span> / <span class="failed-text">{{ row.failed_count }}</span> / {{ row.total_accounts }}</template></el-table-column><el-table-column prop="created_at" label="创建时间" /><el-table-column label="操作" width="90"><template #default="{ row }"><el-button link type="primary" @click="openJob(row)">查看结果</el-button></template></el-table-column></el-table>
          <el-divider /><div class="sub-head">Meta 同步任务</div><el-table :data="metaTasks" size="small"><el-table-column prop="task_id" label="Celery Task ID" show-overflow-tooltip /><el-table-column prop="task_type" label="类型" /><el-table-column prop="object_type" label="对象" /><el-table-column prop="status" label="状态" /><el-table-column prop="result_summary" label="结果" show-overflow-tooltip /><el-table-column prop="created_at" label="提交时间" /></el-table>
          <el-divider /><div class="sub-head">启停 / 归档 / 移除记录</div><el-table :data="deliveryActions" size="small"><el-table-column prop="action" label="动作" width="100" /><el-table-column prop="object_type" label="对象类型" width="110" /><el-table-column prop="object_id" label="对象 ID" show-overflow-tooltip /><el-table-column prop="status" label="状态" width="110" /><el-table-column prop="desired_status" label="目标状态" width="110" /><el-table-column prop="remote_status" label="Meta 状态" width="110" /><el-table-column prop="error_message" label="失败原因" show-overflow-tooltip /><el-table-column prop="created_at" label="提交时间" /><el-table-column label="操作" width="110"><template #default="{ row }"><el-button v-if="row.status === 'FAILED'" link type="warning" @click="retryAction(row)">重试</el-button><el-button link type="primary" @click="showActionDetail(row)">详情</el-button></template></el-table-column></el-table>
          <el-empty v-if="!jobLoading && !jobs.length && !metaTasks.length && !deliveryActions.length" description="暂无异步任务" />
        </el-card>
      </el-tab-pane>
    </el-tabs>
    <el-dialog v-model="detailVisible" title="投放对象详情" width="820px"><div v-if="detail" class="detail-content"><el-descriptions :column="2" border><el-descriptions-item label="对象类型">{{ typeLabel(detail.object_type) }}</el-descriptions-item><el-descriptions-item label="对象名称">{{ detail.object?.name || detail.campaign?.name || '-' }}</el-descriptions-item><el-descriptions-item label="本地 ID">{{ detail.object?.id || '-' }}</el-descriptions-item><el-descriptions-item label="Meta ID">{{ metaObjectId(detail) }}</el-descriptions-item><el-descriptions-item label="系统状态"><el-tag>{{ detail.object?.status || detail.campaign?.status || '-' }}</el-tag></el-descriptions-item><el-descriptions-item label="Meta 状态"><el-tag :type="(detail.object?.meta_status || detail.campaign?.meta_status) === 'ACTIVE' ? 'success' : 'warning'">{{ detail.object?.meta_status || detail.campaign?.meta_status || '未同步' }}</el-tag></el-descriptions-item><el-descriptions-item label="目标状态">{{ detail.object?.desired_status || detail.campaign?.desired_status || '-' }}</el-descriptions-item><el-descriptions-item label="最近同步">{{ detail.object?.last_synced_at || detail.campaign?.last_synced_at || '未同步' }}</el-descriptions-item><el-descriptions-item label="广告账户" :span="2">{{ detail.account?.account_name || detail.account?.account_id || detail.campaign?.ad_account_id || '-' }}</el-descriptions-item><el-descriptions-item v-if="detail.object?.last_error || detail.campaign?.last_error" label="同步异常" :span="2"><span class="failed-text">{{ detail.object?.last_error || detail.campaign?.last_error }}</span></el-descriptions-item></el-descriptions><div v-if="detail.ancestors?.campaign || detail.ancestors?.adset" class="detail-section"><h4>所属层级</h4>{{ detail.ancestors.campaign?.name || '' }}<span v-if="detail.ancestors.adset"> / {{ detail.ancestors.adset.name }}</span></div><div v-if="detail.children?.length || detail.adsets?.length" class="detail-section"><h4>下级对象</h4><el-table :data="detail.children || detail.adsets || []" size="small"><el-table-column prop="name" label="名称" /><el-table-column prop="meta_adset_id" label="Meta AdSet ID" /><el-table-column prop="meta_ad_id" label="Meta Ad ID" /><el-table-column prop="status" label="状态" /><el-table-column prop="meta_status" label="Meta 状态" /><el-table-column v-if="detail.object_type === 'CAMPAIGN'" label="广告数"><template #default="{ row }">{{ row.ads?.length || 0 }}</template></el-table-column></el-table></div><div class="detail-section"><h4>最近操作结果</h4><el-table :data="detail.recent_actions || []" size="small"><el-table-column prop="action" label="动作" /><el-table-column prop="status" label="状态" /><el-table-column prop="remote_status" label="Meta 状态" /><el-table-column prop="error_message" label="失败原因" show-overflow-tooltip /><el-table-column prop="created_at" label="时间" /></el-table><el-empty v-if="!detail.recent_actions?.length" description="暂无对象操作记录" /></div><div v-if="detail.legacy?.job_item?.response_payload?.cleanup_attempted" class="detail-section"><el-alert :type="detail.legacy.job_item.response_payload.cleanup_failed ? 'error' : 'success'" :title="detail.legacy.job_item.response_payload.cleanup_failed ? '发布失败，部分 Meta 对象未清理' : '发布失败，Meta 对象已自动回滚'" show-icon /></div><div v-if="detail.legacy?.creative_config" class="detail-section"><h4>创意与落地页</h4><pre class="detail-json">{{ JSON.stringify(detail.legacy.creative_config?.creative_format === 'CAROUSEL' ? detail.legacy.creative_config?.carousel_cards || [] : detail.legacy.creative_config?.creatives || [], null, 2) }}</pre></div></div></el-dialog>
    <el-dialog v-model="jobDetailVisible" title="批量操作结果" width="820px"><div v-if="jobDetail"><el-descriptions :column="4" border><el-descriptions-item label="动作">{{ jobDetail.action_type }}</el-descriptions-item><el-descriptions-item label="状态">{{ jobDetail.status }}</el-descriptions-item><el-descriptions-item label="成功">{{ jobDetail.success_count }}</el-descriptions-item><el-descriptions-item label="失败">{{ jobDetail.failed_count }}</el-descriptions-item></el-descriptions><el-table :data="jobDetail.items || []" size="small" style="margin-top: 16px"><el-table-column prop="ad_account_id" label="广告账户" /><el-table-column prop="status" label="结果" /><el-table-column prop="error_code" label="错误码" /><el-table-column prop="error_message" label="失败原因" show-overflow-tooltip /><el-table-column prop="updated_at" label="完成时间" /></el-table></div></el-dialog>
  </div>
</template>
<script setup lang="ts">
import { onBeforeUnmount, onMounted, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { campaignsApi, type DeliveryAction, type DeliveryObjectDetail, type MetaAd, type MetaAdSet, type MetaCampaign } from '@/api/campaigns'
import { jobsApi, type CampaignJob } from '@/api/jobs'
type DeliveryRow = MetaCampaign | MetaAdSet | MetaAd
type ObjectType = 'CAMPAIGN' | 'ADSET' | 'AD'
const activeTab = ref('campaigns'); const loading = ref(false); const subLoading = ref(false); const jobLoading = ref(false)
const campaigns = ref<MetaCampaign[]>([]); const adsets = ref<MetaAdSet[]>([]); const ads = ref<MetaAd[]>([]); const jobs = ref<CampaignJob[]>([]); const metaTasks = ref<any[]>([]); const deliveryActions = ref<DeliveryAction[]>([])
const selectedCampaign = ref<MetaCampaign | null>(null); const selectedAdset = ref<MetaAdSet | null>(null); const selectedCampaigns = ref<MetaCampaign[]>([]); const selectedAdsets = ref<MetaAdSet[]>([]); const selectedAds = ref<MetaAd[]>([])
const selectedCampaignId = ref(''); const selectedAdsetId = ref(''); const adsetStatusFilter = ref(''); const adStatusFilter = ref('')
const detailVisible = ref(false); const detail = ref<DeliveryObjectDetail & { legacy?: any } | null>(null); const jobDetailVisible = ref(false); const jobDetail = ref<any>(null)
const accountFilter = ref(''); const statusFilter = ref(''); const keywordFilter = ref(''); const taskNotice = ref(''); const taskNoticeType = ref<'info' | 'success' | 'warning' | 'error'>('info')
const batchResult = ref<{ title: string; count: number; message: string; failed?: boolean } | null>(null)
let refreshTimer: ReturnType<typeof setTimeout> | undefined; let taskTimer: ReturnType<typeof setTimeout> | undefined; let jobTimer: ReturnType<typeof setTimeout> | undefined
async function loadCampaigns() { loading.value = true; try { const { data } = await campaignsApi.list({ keyword: keywordFilter.value || undefined, ad_account_id: accountFilter.value || undefined, status: statusFilter.value || undefined }); campaigns.value = data } finally { loading.value = false } }
function typeLabel(type: string) { return type === 'CAMPAIGN' ? '广告系列' : type === 'ADSET' ? '广告组' : '广告' }
function metaObjectId(value: any) { return value.object?.meta_campaign_id || value.object?.meta_adset_id || value.object?.meta_ad_id || value.campaign?.meta_campaign_id || '-' }
async function showDetail(row: DeliveryRow, type: ObjectType) { try { if (type === 'CAMPAIGN') { const { data } = await campaignsApi.detail(row.id); detail.value = { object_type: type, object: data.campaign, account: data.account, ancestors: {}, children: data.adsets || [], recent_actions: [], legacy: data } } else { const { data } = await campaignsApi.objectDetail(type, row.id); detail.value = data } detailVisible.value = true } catch (error: any) { ElMessage.error(error?.response?.data?.detail || '加载详情失败') } }
async function openAdsets(row: MetaCampaign) { selectedCampaign.value = row; selectedCampaignId.value = row.id; selectedAdset.value = null; selectedAdsetId.value = ''; selectedAdsets.value = []; ads.value = []; activeTab.value = 'adsets'; await loadAdsets(row.id) }
async function loadAdsets(id: string) { subLoading.value = true; try { const { data } = await campaignsApi.adsets(id, adsetStatusFilter.value || undefined); adsets.value = data } catch (error: any) { adsets.value = []; ElMessage.error(error?.response?.data?.detail || '加载广告组失败') } finally { subLoading.value = false } }
async function selectCampaign(id?: string) { const row = campaigns.value.find(item => item.id === id); selectedCampaign.value = row || null; selectedAdset.value = null; selectedAdsetId.value = ''; selectedAdsets.value = []; ads.value = []; if (id) await loadAdsets(id); else adsets.value = [] }
async function openAds(row: MetaAdSet) { selectedAdset.value = row; selectedAdsetId.value = row.id; selectedAds.value = []; activeTab.value = 'ads'; await loadAds(row.id) }
async function loadAds(id: string) { subLoading.value = true; try { const { data } = await campaignsApi.ads(id, adStatusFilter.value || undefined); ads.value = data } catch (error: any) { ads.value = []; ElMessage.error(error?.response?.data?.detail || '加载广告失败') } finally { subLoading.value = false } }
async function selectAdset(id?: string) { const row = adsets.value.find(item => item.id === id); selectedAdset.value = row || null; selectedAds.value = []; if (id) await loadAds(id); else ads.value = [] }
function watchTasks(taskIds: string[]) { if (!taskIds.length) return; if (taskTimer) clearTimeout(taskTimer); let round = 0; const poll = async () => { const statuses = await Promise.all(taskIds.map(id => campaignsApi.taskStatus(id).then(({ data }) => data).catch(() => ({ task_id: id, state: 'UNKNOWN' })))); const finished = statuses.filter(item => ['SUCCESS', 'FAILURE', 'REVOKED'].includes(item.state)); const failed = statuses.filter(item => ['FAILURE', 'REVOKED'].includes(item.state)); const partial = statuses.filter(item => item.result?.status === 'partial_success'); const errorCount = statuses.reduce((sum, item) => sum + Number(item.result?.error_count || 0), 0); taskNoticeType.value = failed.length ? 'error' : partial.length || errorCount ? 'warning' : finished.length === statuses.length ? 'success' : 'info'; taskNotice.value = finished.length === statuses.length ? (failed.length ? `任务完成：${failed.length} 个失败` : partial.length || errorCount ? `任务完成，但有 ${errorCount || partial.length} 项同步异常` : 'Meta 任务已完成，页面状态已刷新') : `Meta 任务执行中：${finished.length}/${statuses.length}`; if (finished.length === statuses.length || round++ >= 30) { await refresh(); return } taskTimer = setTimeout(poll, 2000) }; poll() }
function watchJobs(jobIds: string[]) { if (!jobIds.length) return; if (jobTimer) clearTimeout(jobTimer); let round = 0; const poll = async () => { const rows = await Promise.all(jobIds.map(id => jobsApi.get(id).then(({ data }) => data).catch(() => null))); const valid = rows.filter(Boolean) as CampaignJob[]; const finished = valid.filter(row => ['SUCCESS', 'PARTIAL_SUCCESS', 'FAILED', 'CANCELLED'].includes(row.status)); const failed = valid.reduce((sum, row) => sum + Number(row.failed_count || 0), 0); if (finished.length === valid.length && valid.length) { batchResult.value = { title: '批量操作已完成', count: valid.reduce((sum, row) => sum + Number(row.total_accounts || 0), 0), message: `成功 ${valid.reduce((sum, row) => sum + Number(row.success_count || 0), 0)}，失败 ${failed}`, failed: failed > 0 }; await refresh(); return } if (round++ >= 30) { batchResult.value = { title: '批量操作仍在执行', count: valid.reduce((sum, row) => sum + Number(row.total_accounts || 0), 0), message: '请在任务列表中查看最新结果' }; return } jobTimer = setTimeout(poll, 2000) }; poll() }
async function sync() { await syncSelected('CAMPAIGN', campaigns.value) }
async function syncSelected(type: ObjectType, rows: DeliveryRow[]) { if (!rows.length) { ElMessage.warning('请先选择投放对象'); return } try { const { data } = await campaignsApi.sync(rows.map(row => row.id), type); ElMessage.success(`已提交 ${rows.length} 个${typeLabel(type)}的 Meta 状态同步`); taskNotice.value = 'Meta 实时状态同步已提交'; batchResult.value = { title: 'Meta 状态同步', count: rows.length, message: `已按 ${data.account_ids?.length || 0} 个广告账户执行同步` }; activeTab.value = 'jobs'; await loadJobs(); watchTasks(data.task_ids || []) } catch (error: any) { ElMessage.error(error?.response?.data?.detail || '提交同步任务失败') } }
async function batchAction(action: string, type: ObjectType, rows: DeliveryRow[]) { if (!rows.length) { ElMessage.warning('请先选择投放对象'); return } try { await ElMessageBox.confirm(`确认对选中的 ${rows.length} 个${typeLabel(type)}执行「${action}」？`, '确认批量操作', { type: 'warning' }); const { data } = await campaignsApi.action({ action, ids: rows.map(row => row.id), object_type: type, idempotency_key: actionKey(action, rows.map(row => row.id).join(',')) }); batchResult.value = { title: `批量${action}已提交`, count: rows.length, message: data.task_ids?.length ? '正在等待 Meta 返回结果' : '正在按广告账户执行任务' }; taskNotice.value = `批量${action}任务已提交`; activeTab.value = 'jobs'; await loadJobs(); if (data.task_ids?.length) watchTasks(data.task_ids); if (data.job_ids?.length) watchJobs(data.job_ids) } catch (error: any) { if (error?.response?.data?.detail) ElMessage.error(error.response.data.detail) } }
function actionKey(action: string, id: string) { return `${action}:${id}:${Date.now()}:${Math.random().toString(16).slice(2)}` }
async function changeStatus(row: DeliveryRow, type: ObjectType) { await batchAction(row.status === 'ACTIVE' ? 'PAUSE' : 'ENABLE', type, [row]) }
async function archive(row: DeliveryRow, type: ObjectType) { await batchAction('ARCHIVE', type, [row]) }
async function removePublished(row: DeliveryRow, type: ObjectType) { await batchAction('DELETE', type, [row]) }
async function restore(row: DeliveryRow, type: ObjectType) { await batchAction('RESTORE', type, [row]) }
async function retryAction(row: DeliveryAction) { try { await ElMessageBox.confirm('该操作上次执行失败，确认重新提交？原失败记录会保留。', '确认重试', { type: 'warning' }); const { data } = await campaignsApi.retryDeliveryAction(row.id); ElMessage.success('重试任务已提交'); taskNotice.value = '失败操作已重新提交'; await loadJobs(); watchTasks(data.task_id ? [data.task_id] : []) } catch {} }
async function showActionDetail(row: DeliveryAction) { try { const { data } = await campaignsApi.objectDetail(row.object_type, row.object_id); detail.value = data; detailVisible.value = true } catch { ElMessage.error('加载操作对象详情失败') } }
async function loadJobs() { jobLoading.value = true; try { const [{ data: jobData }, { data: taskData }, { data: actionData }] = await Promise.all([jobsApi.list({ limit: 50 }), campaignsApi.taskRecords(50), campaignsApi.deliveryActions(50)]); jobs.value = jobData; metaTasks.value = taskData; deliveryActions.value = actionData } finally { jobLoading.value = false } }
async function openJob(row: CampaignJob) { try { const { data } = await jobsApi.get(row.id); jobDetail.value = data; jobDetailVisible.value = true } catch { ElMessage.error('加载批量任务结果失败') } }
async function refresh() { await loadCampaigns(); await loadJobs() }
async function onTabChange(tab: string | number) { if (tab === 'jobs') await loadJobs(); else if (tab === 'adsets' && !selectedCampaignId.value) adsets.value = []; else if (tab === 'ads' && !selectedAdsetId.value) ads.value = [] }
onMounted(refresh)
onBeforeUnmount(() => { if (refreshTimer) clearTimeout(refreshTimer); if (taskTimer) clearTimeout(taskTimer); if (jobTimer) clearTimeout(jobTimer) })
</script>
